using System.Text.Json;using RAWSelectionAssistant.Core.Services.Color;using RAWSelectionAssistant.Core.Services.Projects;
namespace RAWSelectionAssistant.Tests;
[TestClass]public sealed class WideToneClosureTests
{
 static ColorAdjustmentStackNode Node(int version,double c,double sh,double hi)=>new(Guid.NewGuid(),ColorStudioNodeType.BasicTone,"tone",NumericParameters:new Dictionary<string,double>{{"contrast",c},{"shadows",sh},{"highlights",hi}}){WideToolVersion=version,CompositeVersion=1};
 [TestMethod]public void NewVersionMonotonicExtremesAndOldVersionPreserved(){foreach(double c in new[]{-100d,0,100})foreach(double sh in new[]{-100d,0,100})foreach(double hi in new[]{-100d,0,100}){var tool=new LinearWideToolsV1.Prepared(Node(2,c,sh,hi));double previous=0;for(int i=0;i<3000;i++){double y=Math.Pow(10,-9+i*11d/2999);var v=tool.Apply(new(y,y,y));Assert.IsTrue(v.X>=previous-1e-12,"V2 grey monotonic");Assert.IsTrue(double.IsFinite(v.X));previous=v.X;}}var old=new LinearWideToolsV1.Prepared(Node(1,-100,100,0));var next=new LinearWideToolsV1.Prepared(Node(2,-100,100,0));Assert.AreNotEqual(old.Apply(new(.18,.18,.18)).X,next.Apply(new(.18,.18,.18)).X);foreach(var p in new[]{-.2,0,.179999,.18,.180001,1,4}){var v=next.Apply(new(p,p,p));Assert.IsTrue(double.IsFinite(v.X));if(p<0)Assert.AreEqual(p,v.X);}}
 [TestMethod]public void WarmDirectionAndRgbRatiosAreExplicit(){ColorVector3 Apply(int v,double temperature,double tint)=>new LinearWideToolsV1.Prepared(new(Guid.NewGuid(),ColorStudioNodeType.WhiteBalance,"wb",NumericParameters:new Dictionary<string,double>{{"temperature",temperature},{"tint",tint}}){WideToolVersion=v}).Apply(new(.18,.18,.18));var warm=Apply(2,40,0);var cool=Apply(2,-40,0);Assert.IsTrue(warm.X/warm.Z>1);Assert.IsTrue(cool.X/cool.Z<1);var magenta=Apply(2,0,30);Assert.IsTrue((magenta.X+magenta.Z)/2>magenta.Y);var tool=new LinearWideToolsV1.Prepared(Node(2,70,80,-70));var rgb=new ColorVector3(-.1,.4,2);var result=tool.Apply(rgb);Assert.AreEqual(rgb.X/rgb.Z,result.X/result.Z,1e-12);Assert.IsTrue(result.X<0);Assert.IsTrue(result.Z>1);}
 [TestMethod]public void MatureNativeReferenceCurvesAreExecutedAndDifferencesRecorded(){var path=Environment.GetEnvironmentVariable("KITAO_TONE_NATIVE_REFERENCE");if(path is null){Assert.Inconclusive("Pinned native source execution required");return;}using var doc=JsonDocument.Parse(File.ReadAllText(path));var rows=new List<object>();foreach(var r in doc.RootElement.GetProperty("darktable").GetProperty("cases").EnumerateArray()){double x=r.GetProperty("x").GetDouble(),exponent=r.GetProperty("exponent").GetDouble(),reference=r.GetProperty("y").GetDouble();var own=new LinearWideToolsV1.Prepared(Node(2,(exponent-1)*100,0,0)).Apply(new(x,x,x));Assert.IsTrue(double.IsFinite(reference));rows.Add(new{engine="darktable",x,parameter=exponent,reference,product=own.X,difference=own.X-reference});}foreach(var r in doc.RootElement.GetProperty("rawtherapee").GetProperty("cases").EnumerateArray()){double x=r.GetProperty("x").GetDouble();double? reference=r.GetProperty("y").ValueKind==JsonValueKind.Null?null:r.GetProperty("y").GetDouble();var own=new LinearWideToolsV1.Prepared(Node(2,0,20,-20)).Apply(new(x,x,x));rows.Add(new{engine="RawTherapee",x,a=r.GetProperty("a").GetDouble(),b=r.GetProperty("b").GetDouble(),reference,product=own.X});}var output=Environment.GetEnvironmentVariable("KITAO_TONE_OUTPUT");if(output is not null){Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"REFERENCE_CURVE_DIFFERENCES.json"),JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));}}
 [TestMethod]public void SaturatedThinMaskStrongNodesAndRotatedCropUseExactPathAtOriginalBudget()
 {
  using var cms=new RAWSelectionAssistant.Core.Services.Color.ControlledIcc.LcmsRgbEngine();var state=new RAWSelectionAssistant.Core.Services.Color.ControlledIcc.DocumentColorStateV1(cms.StandardProfile("DisplayP3"),cms.StandardProfile("LinearProPhotoD50V2"),cms.StandardProfile("sRGB"),Version:2);
  var pixels=Enumerable.Range(0,240*160).SelectMany(i=>i%2==0?new[]{1.4f,-.15f,.05f}:new[]{.02f,1.3f,1.2f}).ToArray();var baseDefinition=new ProfessionalRawDefinition(ProcessingVersion:5,WhiteBalance:"Rendered",InputConfiguration:"RenderedSrgbFloatV1",DisplayTransform:"RenderedSrgbIdentityV1"){RenderedInputVersion=2,ColorState=state};
  foreach(var scenario in new[]{"highfreq","thinmask","strongWB","strongtone","multinode","rotatedcrop"}){var tone=Node(2,20,20,-20);if(scenario=="strongtone")tone=Node(2,90,80,-90);if(scenario=="thinmask")tone=tone with{LocalMask=new([new([new(.2,.2),new(.8,.7)],.002,0,1,1)])};var nodes=scenario=="multinode"?new[]{tone,tone with{Id=Guid.NewGuid()},tone with{Id=Guid.NewGuid()}}:scenario=="strongWB"?new[]{new ColorAdjustmentStackNode(Guid.NewGuid(),ColorStudioNodeType.WhiteBalance,"WB",NumericParameters:new Dictionary<string,double>{{"temperature",90},{"tint",80}}){WideToolVersion=2}}:new[]{tone};var d=baseDefinition with{LocalEdits=new(new(nodes,ProcessingVersion:2),2),Geometry=scenario=="rotatedcrop"?new(.1,.1,.8,.8,1){Version=2,StraightenDegrees=7}:null};var casePixels=scenario=="highfreq"?pixels:Enumerable.Range(0,240*160*3).Select(i=>.05f+(i%720)/1000f).ToArray();var m=new ProfessionalRawMaster(new(240,160,casePixels,"32f",DocumentWorkingRendererV2.Space),new("synthetic","test","RGB",new string('a',64),d.DecodeKey,[],[],[],65535,OutputSpace:DocumentWorkingRendererV2.Space));Assert.IsTrue(DocumentWorkingRendererV2.RequiresExactPreview(m,d),scenario);using var actual=DocumentWorkingRendererV2.InteractivePreview(m,d,null,120,CancellationToken.None);using var exact=DocumentWorkingRendererV2.Preview(m,d,120,CancellationToken.None);CollectionAssert.AreEqual(exact.Rgb32.ToArray(),actual.Rgb32.ToArray(),scenario+" must fallback, no budget widening");}
 }
 [TestMethod]public void RiskyProxyCasesFallBackBeforeRendering(){var n=Node(2,90,80,-90) with{LocalMask=new([new([new(.5,.5)],.002,0,1,1)])};var d=new ProfessionalRawDefinition{LocalEdits=new(new([n],ProcessingVersion:2)),Geometry=new(.1,.1,.8,.8,1)};Assert.IsFalse(WidePreviewSafety.CanApproximate(d));using var edge=new HighBitDepthImageBuffer(64,1,Enumerable.Range(0,64).SelectMany(i=>i%2==0?new[]{1.4f,-.2f,0}:new[]{0f,1.3f,1.2f}).ToArray());Assert.IsTrue(WidePreviewSafety.SourceHasHighFrequencyBoundary(edge));Assert.IsTrue(WidePreviewSafety.CanApproximate(new ProfessionalRawDefinition{LocalEdits=new(new([Node(2,20,20,-20)],ProcessingVersion:2))}));}
}
